mapper.update:
UPDATE ticket
   SET assignee_id = #{assigneeId},
       status      = 'ASSIGNED',
       version     = version + 1,
       updated_at  = #{now}
 WHERE id = #{id}
   AND version = #{expectedVersion}
   AND status = #{fromStatus}

UPDATE ticket
   SET status      = #{toStatus},
       version     = version + 1,
       updated_at  = #{now},
       resolved_at = #{resolvedAt}
 WHERE id = #{id}
   AND version = #{expectedVersion}
   AND status = #{fromStatus}
